"use client"

import { createParts } from "@ui-sdk/react/primitive"
import { LocateFixedIcon, RefreshCwIcon } from "lucide-react"
import { useId, useRef, useState } from "react"

import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { skyConditions } from "@/components/ui/live-sky-conditions"
import { liveSkyLabels, type LiveSkyLabels } from "@/components/ui/live-sky-labels"
import type { LiveSkyPhoto, LiveSkyPhotoView } from "@/components/ui/live-sky-photo"
import {
  LiveSkyCalibration,
  liveSkyPhotoLabels,
  type LiveSkyPhotoLabels,
} from "@/components/ui/live-sky-photo-controls"
import { liveSky } from "@/components/ui/live-sky-primitive"
import { LiveSkySearch } from "@/components/ui/live-sky-search"
import {
  openMeteo,
  roundedLocation,
  type PlaceSearcher,
  type SkyLocation,
  type SkyPlace,
  type SkyWeather,
  type WeatherFetcher,
} from "@/components/ui/live-sky-weather"
import { Spinner } from "@/components/ui/spinner"
import { Toggle } from "@/components/ui/toggle"
import { useLiveSkyGeolocation } from "@/components/ui/use-live-sky-geolocation"
import { useLiveSkyPhoto } from "@/components/ui/use-live-sky-photo"
import { useLiveSkyScene, useSkyTime } from "@/components/ui/use-live-sky-scene"
import { useLiveSkyWeather } from "@/components/ui/use-live-sky-weather"
import { cn, cssVars } from "@/lib/utils"

const { Root: LiveSkyRoot } = createParts(liveSky, { root: "div" })

/** Fixed weather, time and place, for demos and tests: nothing is fetched and the actions refuse with why. */
type LiveSkySimulation = {
  /** Merged over a fair, mild day. */
  weather: Partial<SkyWeather>
  /** The moment to show, in ms since the epoch or as a Date. */
  time: number | Date
  location: SkyLocation
}

type LiveSkyState = { status: "idle" | "loading" | "ready" | "refreshing" | "error" | "simulated" }

type LiveSkyProps = {
  /** The accessible name of the sky as a whole; agents find it by this. */
  label: string
  /** A place, or `"geolocate"` (the default) to offer a button that asks the browser where the person is. */
  location?: SkyLocation | "geolocate"
  /** Runs when the person or an agent picks a place or locates themselves. Nothing is stored unless you store it. */
  onLocationChange?: (location: SkyLocation) => void
  /** Fetches the weather; Open-Meteo's free, non-commercial API by default (`createOpenMeteo` for a key or another host). */
  fetchWeather?: WeatherFetcher
  /** Looks places up by name for the search; Open-Meteo's geocoder by default, `false` for no search. */
  searchPlaces?: PlaceSearcher | false
  /** Runs with each weather answer, the first and every refresh. */
  onWeather?: (weather: SkyWeather, location: SkyLocation) => void
  /** How often the weather is fetched again while the sky is on screen, in ms. Defaults to 10 minutes. */
  refreshMs?: number
  /** Shows this weather, time and place instead of fetching. */
  simulate?: LiveSkySimulation
  /**
   * A photo of the place to show the live sky in instead of the drawn street: its sky is replaced by the weather now,
   * with the sun and moon where they stand through its lens, and the rest is relit; rain and the glass fall over it.
   * Without a `location`, the photo's EXIF position is used, rounded.
   */
  photo?: LiveSkyPhoto
  /** Runs with the photo and its resolved view each time it is calibrated, for the app to keep; nothing is stored here. */
  onPhotoChange?: (photo: LiveSkyPhoto & LiveSkyPhotoView) => void
  /** Drops landing and running down a pane of glass in front of the sky. On by default. */
  glass?: boolean
  /** Formats the temperature, rain and wind; the page's language by default. */
  locale?: string
  labels?: Partial<Omit<LiveSkyLabels, "conditions" | "sun">> &
    Partial<LiveSkyPhotoLabels> & {
      conditions?: Partial<LiveSkyLabels["conditions"]>
      sun?: Partial<LiveSkyLabels["sun"]>
    }
  /** Classes for the root; a function gets the sky's state. */
  className?: string | ((state: LiveSkyState) => string | undefined)
  /** Called with each frame's drawing time in ms, for measuring. */
  onFrame?: (milliseconds: number) => void
}

const defaultRefreshMs = 10 * 60_000

const fairWeather: SkyWeather = {
  time: 0,
  temperature: 15,
  precipitation: 0,
  rain: 0,
  showers: 0,
  snowfall: 0,
  cloudCover: 35,
  weatherCode: 2,
  windSpeed: 9,
  windDirection: 240,
  visibility: 24_000,
  isDay: true,
  nextHours: [],
}

const minutesPerDegreeOfLongitude = 4
const guessedLatitude = 40

function placeFromClock(): SkyLocation {
  return { latitude: guessedLatitude, longitude: -new Date().getTimezoneOffset() / minutesPerDegreeOfLongitude }
}

const coordinates = (location: SkyLocation, locale: string | undefined) => {
  const degrees = new Intl.NumberFormat(locale, { maximumFractionDigits: 2, minimumFractionDigits: 2 })
  return `${degrees.format(location.latitude)}°, ${degrees.format(location.longitude)}°`
}

function formatters(locale: string | undefined) {
  return {
    temperature: new Intl.NumberFormat(locale, { style: "unit", unit: "celsius", maximumFractionDigits: 0 }),
    rate: new Intl.NumberFormat(locale, { style: "unit", unit: "millimeter-per-hour", maximumFractionDigits: 1 }),
    wind: new Intl.NumberFormat(locale, { style: "unit", unit: "kilometer-per-hour", maximumFractionDigits: 0 }),
  }
}

/**
 * The sky over a place right now, seen looking up between buildings: the real weather from Open-Meteo (or your
 * fetcher) drawn with WebGL, the sun and moon where they stand, rain that falls toward you and runs down the glass.
 * The scene is decorative; a readout and a summary sentence carry what it shows.
 */
function LiveSky({
  label,
  location = "geolocate",
  onLocationChange,
  fetchWeather = openMeteo.fetchWeather,
  searchPlaces = openMeteo.searchPlaces,
  onWeather,
  refreshMs = defaultRefreshMs,
  simulate,
  photo,
  onPhotoChange,
  glass = true,
  locale,
  labels: overrides,
  className,
  onFrame,
}: LiveSkyProps) {
  const labels: LiveSkyLabels & LiveSkyPhotoLabels = {
    ...liveSkyLabels,
    ...liveSkyPhotoLabels,
    ...overrides,
    conditions: { ...liveSkyLabels.conditions, ...overrides?.conditions },
    sun: { ...liveSkyLabels.sun, ...overrides?.sun },
  }
  const summaryId = useId()
  const stage = useRef<HTMLDivElement>(null)
  const [locating, setLocating] = useState(false)
  const [locateFailed, setLocateFailed] = useState(false)
  const given = typeof location === "object" ? location : null
  const givenKey = given ? `${String(given.latitude)},${String(given.longitude)},${given.name ?? ""}` : "geolocate"
  const [chosen, setChosen] = useState<{ from: string; location: SkyLocation } | null>(null)
  const picked = chosen?.from === givenKey ? chosen.location : given
  const photoScene = useLiveSkyPhoto({ photo, onPhotoChange, location: simulate?.location ?? picked })
  const photoPlace = photoScene.place ? { ...photoScene.place, name: labels.photoPlace } : null
  const place = simulate?.location ?? picked ?? photoPlace
  const shownPlace = place ? roundedLocation(place) : placeFromClock()
  const [calibrating, setCalibrating] = useState<{ src: string; open: boolean } | null>(null)
  const photoReady = photo !== undefined && photoScene.status === "ready"
  const calibrationOpen = photoReady && (calibrating?.src === photo.src ? calibrating.open : !photoScene.headingKnown)

  const { snapshot, refresh } = useLiveSkyWeather(
    stage,
    simulate || !place ? null : { location: shownPlace, fetchWeather, refreshMs, onWeather },
  )
  const simulatedTime = simulate ? new Date(simulate.time).getTime() : undefined
  const now = useSkyTime(simulatedTime)
  const weather = simulate ? { ...fairWeather, time: now, ...simulate.weather } : snapshot.weather
  const conditions = skyConditions(weather ?? fairWeather, shownPlace, new Date(now))
  useLiveSkyScene(stage, { conditions, location: shownPlace, glass, onFrame, photo: photoScene.shown })

  const geolocation = useLiveSkyGeolocation({
    autoLocate: location === "geolocate" && !picked && !simulate,
    onLocated: (found) => choose({ ...found, name: labels.here }),
  })

  function choose(next: SkyLocation) {
    setChosen({ from: givenKey, location: next })
    onLocationChange?.(next)
  }
  const locate = () => {
    setLocating(true)
    setLocateFailed(false)
    return geolocation.locate().then(
      (found) => {
        setLocating(false)
        const named = { ...found, name: labels.here }
        choose(named)
        return named
      },
      (error: unknown) => {
        setLocating(false)
        setLocateFailed(true)
        throw error
      },
    )
  }
  const searchFor = (name: string) => {
    if (!searchPlaces) return Promise.reject(new Error("This sky has no place search."))
    return searchPlaces(name, { signal: new AbortController().signal }).then((results: SkyPlace[]) => {
      const first = results[0]
      if (!first) throw new Error(labels.noPlaces(name))
      choose(first)
      return first
    })
  }

  const calibrate = (view: { heading: number; fov?: number | undefined; horizon?: number | undefined }) =>
    photoScene.setView({
      heading: view.heading,
      ...(view.fov === undefined ? {} : { fov: view.fov }),
      ...(view.horizon === undefined ? {} : { horizon: view.horizon }),
    })
  const status: LiveSkyState["status"] = simulate ? "simulated" : snapshot.status
  const format = formatters(locale)
  const placeName = place ? (place.name ?? coordinates(place, locale)) : null
  const ready = weather !== null && place !== null
  const conditionText = labels.conditions[conditions.condition]
  const temperature = format.temperature.format(conditions.temperature)
  const summary = ready
    ? labels.summary({
        condition: conditionText,
        temperature,
        sun: labels.sun[conditions.sunState],
        place: placeName ?? "",
      })
    : place
      ? status === "error"
        ? labels.failed
        : labels.loading
      : labels.noPlace

  return (
    <LiveSkyRoot
      aria-label={label}
      aria-describedby={summaryId}
      summary={summary}
      place={placeName ?? ""}
      simulated={Boolean(simulate)}
      hasLocation={place !== null}
      geolocation={geolocation.access}
      handlers={{
        setLocation: choose,
        searchPlace: searchPlaces ? searchFor : undefined,
        geolocate: locate,
        refresh,
        calibrate: photo ? calibrate : undefined,
      }}
      data-status={status}
      className={cn(
        "flex w-full flex-col overflow-hidden rounded-surface border bg-card text-card-foreground shadow-surface",
        typeof className === "function" ? className({ status }) : className,
      )}
    >
      <div
        ref={stage}
        data-slot="live-sky-scene"
        data-rain={conditions.rainKind}
        data-photo={photo ? "" : undefined}
        data-marking={photoScene.marking ? "" : undefined}
        aria-hidden="true"
        style={photo ? cssVars({ "--live-sky-aspect": String(photoScene.aspect) }) : undefined}
        onPointerDown={photoScene.onPointerDown}
      />
      {calibrationOpen ? (
        <div className="px-inset-surface pt-inset-surface">
          <LiveSkyCalibration
            view={photoScene.view}
            marking={photoScene.marking}
            labels={labels}
            onView={photoScene.setView}
            onMarking={photoScene.setMarking}
            format={(value) => new Intl.NumberFormat(locale).format(value)}
          />
        </div>
      ) : null}
      <div data-slot="live-sky-panel" className="flex flex-wrap items-start justify-between gap-group p-inset-surface">
        <div className="flex min-w-48 grow basis-0 flex-col gap-inline">
          <div className="flex flex-wrap items-center gap-inline">
            <span className="text-title-sm tracking-tight">{placeName ?? labels.noPlace}</span>
            {simulate ? <Badge variant="outline">{labels.simulated}</Badge> : null}
            {photo && photoReady ? (
              <Toggle
                variant="outline"
                size="sm"
                pressed={calibrationOpen}
                onPressedChange={(open) => setCalibrating({ src: photo.src, open })}
              >
                {labels.calibrate}
              </Toggle>
            ) : null}
          </div>
          {photoScene.status === "reading" || photoScene.status === "failed" ? (
            <span className="flex items-center gap-inline text-caption text-muted-foreground">
              {photoScene.status === "reading" ? <Spinner size="sm" /> : null}
              {photoScene.status === "reading" ? labels.readingPhoto : labels.photoFailed}
            </span>
          ) : null}
          {ready ? (
            <div className="flex flex-wrap items-baseline gap-x-items">
              <span className="text-display-sm tabular-nums">{temperature}</span>
              <span className="text-body text-muted-foreground">{conditionText}</span>
            </div>
          ) : place && status === "error" ? (
            <div className="flex flex-wrap items-center gap-items">
              <span className="text-body-sm text-muted-foreground">{labels.failed}</span>
              <Button size="sm" variant="outline" onClick={() => refresh().catch(() => undefined)}>
                {labels.retry}
              </Button>
            </div>
          ) : place ? (
            <span className="flex items-center gap-inline text-body-sm text-muted-foreground">
              <Spinner size="sm" />
              {labels.loading}
            </span>
          ) : null}
          {ready ? (
            <dl className="flex flex-wrap gap-x-group gap-y-inline text-body-sm">
              <div className="flex gap-inline">
                <dt className="text-muted-foreground">{labels.precipitation}</dt>
                <dd className="tabular-nums">{format.rate.format(weather.precipitation)}</dd>
              </div>
              <div className="flex gap-inline">
                <dt className="text-muted-foreground">{labels.wind}</dt>
                <dd className="tabular-nums">{format.wind.format(weather.windSpeed)}</dd>
              </div>
            </dl>
          ) : null}
          <p id={summaryId} className="sr-only" aria-live="polite">
            {summary}
          </p>
        </div>
        {simulate ? null : (
          <div className="flex w-full max-w-sm grow basis-64 flex-col gap-items">
            <div className="flex items-center gap-items">
              {searchPlaces ? (
                <div className="min-w-0 grow">
                  <LiveSkySearch searchPlaces={searchPlaces} onPlace={choose} labels={labels} />
                </div>
              ) : null}
              {place ? (
                <Button
                  size="icon"
                  variant="ghost"
                  aria-label={labels.refresh}
                  loading={status === "refreshing" || status === "loading"}
                  onClick={() => refresh().catch(() => undefined)}
                >
                  <RefreshCwIcon />
                </Button>
              ) : null}
            </div>
            {location === "geolocate" ? (
              <div className="flex flex-wrap items-center gap-items">
                <Button
                  variant="outline"
                  size="sm"
                  disabled={geolocation.access === "denied" || geolocation.access === "unsupported"}
                  loading={locating}
                  onClick={() => locate().catch(() => undefined)}
                >
                  <LocateFixedIcon />
                  {locating ? labels.locating : labels.geolocate}
                </Button>
                {geolocation.access === "denied" ? (
                  <span className="text-caption text-muted-foreground">{labels.locationDenied}</span>
                ) : locateFailed ? (
                  <span className="text-caption text-muted-foreground">{labels.locationFailed}</span>
                ) : null}
              </div>
            ) : null}
          </div>
        )}
      </div>
    </LiveSkyRoot>
  )
}

export { LiveSky, liveSkyLabels }
export type { LiveSkyLabels, LiveSkyProps, LiveSkySimulation, LiveSkyState }

import { definePrimitive } from "@ui-sdk/core"

import { isValidLocation, type SkyLocation } from "@/components/ui/live-sky-weather"
import { unavailable } from "@/lib/action-refusal"

/** Whether the browser can tell where the person is: not at all, refused, not asked yet, or allowed. */
type GeolocationAccess = "unsupported" | "denied" | "prompt" | "granted"

/** What the sky's actions do, wired by the component. */
type LiveSkyHandlers = {
  setLocation: (location: SkyLocation) => void
  /** Looks a place up by name and shows its sky; absent when the sky has no place search. */
  searchPlace?: ((name: string) => Promise<SkyLocation>) | undefined
  geolocate: () => Promise<SkyLocation>
  refresh: () => Promise<unknown>
  /** Points the photo's view; absent without a photo. */
  calibrate?:
    | ((view: { heading: number; fov?: number | undefined; horizon?: number | undefined }) => boolean)
    | undefined
}

type LiveSkyOptions = {
  /** The sentence that describes the sky, which agents read as the value. */
  summary?: string
  place?: string
  simulated?: boolean
  hasLocation?: boolean
  geolocation?: GeolocationAccess
  handlers?: LiveSkyHandlers
}

type Call = { action: string; event: Event | undefined }

function ready(options: LiveSkyOptions, { action, event }: Call) {
  if (options.simulated) return unavailable(action, "isn't available while the sky shows simulated weather", { event })
  if (!options.handlers) return unavailable(action, "isn't available: the sky isn't ready", { event })
  return options.handlers
}

const describe = (value: unknown) => (typeof value === "string" ? `"${value}"` : String(value))

function locationFrom(place: unknown, longitude: unknown, name: unknown): SkyLocation | null {
  if (typeof place === "number" && typeof longitude === "number") {
    return { latitude: place, longitude, name: typeof name === "string" ? name : undefined }
  }
  if (typeof place !== "object" || place === null || !("latitude" in place) || !("longitude" in place)) return null
  const { latitude, longitude: east } = place
  if (typeof latitude !== "number" || typeof east !== "number") return null
  const label = "name" in place && typeof place.name === "string" ? place.name : undefined
  return { latitude, longitude: east, name: label }
}

/** The live sky's agent surface: read the summary as the value, and move the sky to a place, to the person, or refresh. */
const liveSky = definePrimitive({
  name: "live-sky",
  options: {
    summary: "value",
    place: "value",
    simulated: "value",
    hasLocation: "value",
    geolocation: "value",
    handlers: "value",
  },
  state: (options: LiveSkyOptions) => ({ value: options.summary ?? "", place: options.place ?? "" }),
  sync: (options) => ({ value: options.summary ?? "", place: options.place ?? "" }),
  api: (context) => ({
    /**
     * Shows the sky over a place: a name to look up (`"A Coruña"`), `{ latitude, longitude, name? }`, or a latitude
     * and longitude in degrees with an optional name. A name resolves to the first match of the place search.
     */
    setLocation(place: SkyLocation | string | number, longitude?: number, name?: string) {
      const call = { action: "setLocation", event: undefined }
      const handlers = ready(context.options(), call)
      if (handlers === false) return false
      if (typeof place === "string") {
        const query = place.trim()
        if (query === "")
          return unavailable("setLocation", "takes a place name or { latitude, longitude }, not an empty name")
        if (!handlers.searchPlace) {
          return unavailable("setLocation", "can't look a place up by name here: pass { latitude, longitude } instead")
        }
        return handlers.searchPlace(query)
      }
      const location = locationFrom(place, longitude, name)
      if (!location || !isValidLocation(location)) {
        return unavailable(
          "setLocation",
          `takes a latitude from -90 to 90 and a longitude from -180 to 180, not ${describe(location?.latitude ?? place)}, ${describe(location?.longitude ?? longitude)}`,
        )
      }
      handlers.setLocation(location)
      return true
    },
    /** Asks the browser where the person is, with their permission, and shows the sky there. */
    geolocate(event?: Event) {
      const call = { action: "geolocate", event }
      const options = context.options()
      const handlers = ready(options, call)
      if (handlers === false) return false
      if (options.geolocation === "unsupported")
        return unavailable("geolocate", "isn't available: this browser can't tell where it is", { event })
      if (options.geolocation === "denied") {
        return unavailable("geolocate", "isn't available: the person denied location access in the browser", { event })
      }
      return handlers.geolocate()
    },
    /**
     * Points the photo's view: `heading` in degrees from north (0 to 360), and optionally the horizontal field of view
     * (20 to 130°) and the horizon (0 to 1 down the photo). Only with a photo.
     */
    calibrate(heading: number, fov?: number, horizon?: number, event?: Event) {
      const call = { action: "calibrate", event }
      const handlers = context.options().handlers
      if (!handlers) return unavailable("calibrate", "isn't available: the sky isn't ready", { event })
      if (!handlers.calibrate) return unavailable("calibrate", "isn't available without a photo", call)
      if (!Number.isFinite(heading) || heading < 0 || heading > 360) {
        return unavailable("calibrate", `takes a heading from 0 to 360°, not ${String(heading)}`, call)
      }
      if (fov !== undefined && (!Number.isFinite(fov) || fov < 20 || fov > 130)) {
        return unavailable("calibrate", `takes a field of view from 20 to 130°, not ${String(fov)}`, call)
      }
      if (horizon !== undefined && (!Number.isFinite(horizon) || horizon < 0 || horizon > 1)) {
        return unavailable("calibrate", `takes a horizon from 0 to 1 down the photo, not ${String(horizon)}`, call)
      }
      return handlers.calibrate({ heading: heading % 360, fov, horizon })
    },
    /** Fetches the weather again now, instead of waiting for the next refresh. */
    refresh(event?: Event) {
      const call = { action: "refresh", event }
      const options = context.options()
      const handlers = ready(options, call)
      if (handlers === false) return false
      if (!options.hasLocation) return unavailable("refresh", "isn't available before the sky has a place", { event })
      return handlers.refresh()
    },
  }),
  slots: (slot) => ({
    root: slot({ role: "group" }),
  }),
  agent: { actions: ["setLocation", "geolocate", "refresh", "calibrate"] },
})

export { liveSky }
export type { GeolocationAccess, LiveSkyHandlers, LiveSkyOptions }

"use client"

import { useAsyncOptions } from "@ui-sdk/react/async-options"
import { ComboboxStatus } from "@ui-sdk/react/combobox"
import { SearchIcon } from "lucide-react"
import { useRef } from "react"

import {
  Combobox,
  ComboboxClear,
  ComboboxContent,
  ComboboxControl,
  ComboboxEmpty,
  ComboboxInput,
  ComboboxItem,
  ComboboxList,
} from "@/components/ui/combobox"
import type { LiveSkyLabels } from "@/components/ui/live-sky-labels"
import type { PlaceSearcher, SkyPlace } from "@/components/ui/live-sky-weather"
import { isRecord } from "@/lib/narrow"

type PlaceOption = { value: string; label: string; detail: string }

const isPlaceOption = (item: unknown): item is PlaceOption =>
  isRecord(item) && typeof item.value === "string" && typeof item.label === "string" && typeof item.detail === "string"

const searchDebounceMs = 300
const minimumQueryLength = 2

type LiveSkySearchProps = {
  searchPlaces: PlaceSearcher
  onPlace: (place: SkyPlace) => void
  labels: LiveSkyLabels
}

/** A place search over the geocoder: debounced, stale answers dropped, each result named with its region and country. */
function LiveSkySearch({ searchPlaces, onPlace, labels }: LiveSkySearchProps) {
  const found = useRef(new Map<string, SkyPlace>())
  const places = useAsyncOptions<PlaceOption>(
    async (query, { signal }) => {
      const results = await searchPlaces(query, { signal })
      for (const place of results) found.current.set(place.id, place)
      return results.map((place) => ({
        value: place.id,
        label: place.name,
        detail: [place.region, place.country].filter(Boolean).join(", "),
      }))
    },
    { debounce: searchDebounceMs, minLength: minimumQueryLength },
  )

  return (
    <Combobox<string>
      items={places.items}
      filter={false}
      status={places.status}
      onQueryChange={(query: string) => places.setQuery(query)}
      itemToLabel={(value: string) => found.current.get(value)?.name ?? value}
      onValueChange={(value: string | null) => {
        const place = value === null ? undefined : found.current.get(value)
        if (place) onPlace(place)
      }}
    >
      <ComboboxControl data-slot="live-sky-search">
        <SearchIcon aria-hidden="true" className="size-4 shrink-0 text-muted-foreground" />
        <ComboboxInput aria-label={labels.search} placeholder={labels.searchPlaceholder} />
        <ComboboxClear />
      </ComboboxControl>
      <ComboboxContent>
        <ComboboxStatus className="sr-only">
          {(state) =>
            state.status === "error"
              ? labels.searchFailed
              : state.loading
                ? labels.searching
                : labels.places(state.count)
          }
        </ComboboxStatus>
        <ComboboxEmpty>
          {(state) =>
            places.status === "error"
              ? labels.searchFailed
              : state.empty && !state.loading && state.query.trim().length >= minimumQueryLength
                ? labels.noPlaces(state.query)
                : null
          }
        </ComboboxEmpty>
        <ComboboxList>
          {(state) =>
            state.items.filter(isPlaceOption).map((option) => (
              <ComboboxItem key={option.value} value={option.value} label={option.label}>
                <span className="flex min-w-0 flex-col">
                  <span className="truncate">{option.label}</span>
                  {option.detail ? (
                    <span className="truncate text-caption text-muted-foreground">{option.detail}</span>
                  ) : null}
                </span>
              </ComboboxItem>
            ))
          }
        </ComboboxList>
      </ComboboxContent>
    </Combobox>
  )
}

export { LiveSkySearch }

import { isRecord } from "@/lib/narrow"

/** A place on Earth in decimal degrees, with the name to show for it. */
type SkyLocation = { latitude: number; longitude: number; name?: string | undefined }

/** A geocoding result: a location with the region and country that tell same-named places apart. */
type SkyPlace = SkyLocation & { id: string; name: string; region?: string | undefined; country?: string | undefined }

/** The weather over a place now. Rates are per hour, whatever interval the source sums over. */
type SkyWeather = {
  /** When it was measured or modelled, in ms since the epoch. */
  time: number
  /** Air temperature at 2 m, in °C. */
  temperature: number
  /** Everything falling, in mm/h. */
  precipitation: number
  /** Rain from large-scale systems, in mm/h. */
  rain: number
  /** Rain from convective showers, in mm/h. */
  showers: number
  /** Snow, in cm/h. */
  snowfall: number
  /** Sky covered by cloud, in % from 0 to 100. */
  cloudCover: number
  /** The WMO weather interpretation code, 0 to 99. */
  weatherCode: number
  /** Wind at 10 m, in km/h. */
  windSpeed: number
  /** Where the wind blows from, in degrees clockwise from north. */
  windDirection: number
  /** How far one can see, in m. */
  visibility: number
  /** Whether the sun is up, as the source says. */
  isDay: boolean
  /** The precipitation of each coming hour, in mm, from the current hour on. */
  nextHours: { time: number; precipitation: number }[]
}

type FetchOptions = { signal: AbortSignal }
type WeatherFetcher = (location: SkyLocation, options: FetchOptions) => Promise<SkyWeather>
type PlaceSearcher = (query: string, options: FetchOptions) => Promise<SkyPlace[]>

/** Where the Open-Meteo requests go. The free endpoints are for non-commercial use; a paid plan has its own hosts and a key. */
type OpenMeteoOptions = {
  /** The forecast endpoint; `https://customer-api.open-meteo.com/v1/forecast` with a commercial key. */
  forecastUrl?: string
  /** The geocoding endpoint; `https://customer-geocoding-api.open-meteo.com/v1/search` with a commercial key. */
  geocodingUrl?: string
  /** Sent as `apikey` on every request. */
  apiKey?: string
  /** The language of place names, as an ISO 639-1 code. */
  language?: string
  /** How many hours of precipitation to read ahead, 1 to 48. */
  hoursAhead?: number
  fetch?: typeof fetch
}

const coordinateDecimals = 2

/** Rounds a coordinate to 2 decimals, about a kilometre, before it leaves the browser. */
const roundCoordinate = (degrees: number) => Number(degrees.toFixed(coordinateDecimals))

const roundedLocation = (location: SkyLocation): SkyLocation => ({
  ...location,
  latitude: roundCoordinate(location.latitude),
  longitude: roundCoordinate(location.longitude),
})

const isValidLocation = (location: SkyLocation) =>
  Number.isFinite(location.latitude) &&
  Number.isFinite(location.longitude) &&
  Math.abs(location.latitude) <= 90 &&
  Math.abs(location.longitude) <= 180

const currentFields = [
  "temperature_2m",
  "precipitation",
  "rain",
  "showers",
  "snowfall",
  "cloud_cover",
  "weather_code",
  "wind_speed_10m",
  "wind_direction_10m",
  "is_day",
  "visibility",
] as const

const numberAt = (record: Record<string, unknown>, key: string, fallback = 0) => {
  const value = record[key]
  return typeof value === "number" && Number.isFinite(value) ? value : fallback
}

const numbersAt = (record: Record<string, unknown>, key: string) => {
  const value = record[key]
  return Array.isArray(value) ? value.map((entry) => (typeof entry === "number" ? entry : 0)) : []
}

const msPerSecond = 1000
const secondsPerHour = 3600
const unlimitedVisibilityM = 50_000

function parseForecast(body: unknown): SkyWeather {
  if (!isRecord(body) || !isRecord(body.current)) throw new Error("Open-Meteo sent no current weather.")
  const current = body.current
  const perHour = secondsPerHour / numberAt(current, "interval", secondsPerHour)
  const hourly = isRecord(body.hourly) ? body.hourly : {}
  const hourTimes = numbersAt(hourly, "time")
  const hourAmounts = numbersAt(hourly, "precipitation")
  return {
    time: numberAt(current, "time") * msPerSecond,
    temperature: numberAt(current, "temperature_2m"),
    precipitation: numberAt(current, "precipitation") * perHour,
    rain: numberAt(current, "rain") * perHour,
    showers: numberAt(current, "showers") * perHour,
    snowfall: numberAt(current, "snowfall") * perHour,
    cloudCover: numberAt(current, "cloud_cover"),
    weatherCode: numberAt(current, "weather_code"),
    windSpeed: numberAt(current, "wind_speed_10m"),
    windDirection: numberAt(current, "wind_direction_10m"),
    visibility: numberAt(current, "visibility", unlimitedVisibilityM),
    isDay: numberAt(current, "is_day", 1) === 1,
    nextHours: hourTimes.map((time, index) => ({
      time: time * msPerSecond,
      precipitation: hourAmounts[index] ?? 0,
    })),
  }
}

const textAt = (record: Record<string, unknown>, key: string) => {
  const value = record[key]
  return typeof value === "string" && value !== "" ? value : undefined
}

function parsePlaces(body: unknown): SkyPlace[] {
  if (!isRecord(body) || !Array.isArray(body.results)) return []
  return body.results.filter(isRecord).flatMap((result) => {
    const name = textAt(result, "name")
    const latitude = result.latitude
    const longitude = result.longitude
    if (!name || typeof latitude !== "number" || typeof longitude !== "number") return []
    return [
      {
        id: String(result.id ?? `${name}:${String(latitude)},${String(longitude)}`),
        name,
        latitude: roundCoordinate(latitude),
        longitude: roundCoordinate(longitude),
        region: textAt(result, "admin1"),
        country: textAt(result, "country"),
      },
    ]
  })
}

async function readJson(response: Response, what: string) {
  if (!response.ok) throw new Error(`${what} answered ${String(response.status)}.`)
  const body: unknown = await response.json()
  return body
}

/** Open-Meteo's forecast and geocoding behind the two fetchers LiveSky takes. No key needed on the free tier. */
function createOpenMeteo(options: OpenMeteoOptions = {}) {
  const forecastUrl = options.forecastUrl ?? "https://api.open-meteo.com/v1/forecast"
  const geocodingUrl = options.geocodingUrl ?? "https://geocoding-api.open-meteo.com/v1/search"
  const send = (url: URL, signal: AbortSignal) => {
    if (options.apiKey) url.searchParams.set("apikey", options.apiKey)
    return (options.fetch ?? fetch)(url, { signal })
  }

  const fetchWeather: WeatherFetcher = async (location, { signal }) => {
    const { latitude, longitude } = roundedLocation(location)
    const url = new URL(forecastUrl)
    url.searchParams.set("latitude", String(latitude))
    url.searchParams.set("longitude", String(longitude))
    url.searchParams.set("current", currentFields.join(","))
    url.searchParams.set("hourly", "precipitation")
    url.searchParams.set("forecast_hours", String(options.hoursAhead ?? 6))
    url.searchParams.set("timeformat", "unixtime")
    url.searchParams.set("timezone", "GMT")
    return parseForecast(await readJson(await send(url, signal), "The forecast"))
  }

  const searchPlaces: PlaceSearcher = async (query, { signal }) => {
    const name = query.trim()
    if (name.length < 2) return []
    const url = new URL(geocodingUrl)
    url.searchParams.set("name", name)
    url.searchParams.set("count", "8")
    url.searchParams.set("format", "json")
    if (options.language) url.searchParams.set("language", options.language)
    return parsePlaces(await readJson(await send(url, signal), "The place search"))
  }

  return { fetchWeather, searchPlaces }
}

const openMeteo = createOpenMeteo()

export { createOpenMeteo, isValidLocation, openMeteo, parseForecast, parsePlaces, roundCoordinate, roundedLocation }
export type { OpenMeteoOptions, PlaceSearcher, SkyLocation, SkyPlace, SkyWeather, WeatherFetcher }

import {
  roundedLocation,
  type SkyLocation,
  type SkyWeather,
  type WeatherFetcher,
} from "@/components/ui/live-sky-weather"

/** Where the weather stands: none asked for yet, the first answer on its way, an answer (maybe being renewed), or a failure. */
type WeatherStatus = "idle" | "loading" | "ready" | "refreshing" | "error"

type WeatherSnapshot = {
  status: WeatherStatus
  weather: SkyWeather | null
  /** The rounded place the weather is for, as `latitude,longitude`. */
  key: string | null
  error: unknown
}

type FeedSettings = {
  location: SkyLocation | null
  fetchWeather: WeatherFetcher
  refreshMs: number
  onWeather?: ((weather: SkyWeather, location: SkyLocation) => void) | undefined
}

const keyOf = (location: SkyLocation | null) => {
  if (!location) return null
  const rounded = roundedLocation(location)
  return `${String(rounded.latitude)},${String(rounded.longitude)}`
}

const noLocationError = () => new Error("The sky has no place to fetch the weather for.")

/** Fetches the weather for one place at a time and renews it every `refreshMs` while `visible`; nothing runs while hidden. */
function createWeatherFeed() {
  let snapshot: WeatherSnapshot = { status: "idle", weather: null, key: null, error: null }
  let settings: FeedSettings | null = null
  let visible = false
  let fetchedAt = 0
  let controller: AbortController | null = null
  let timer: ReturnType<typeof setTimeout> | undefined
  const listeners = new Set<() => void>()

  const set = (next: Partial<WeatherSnapshot>) => {
    snapshot = { ...snapshot, ...next }
    for (const listener of listeners) listener()
  }

  const schedule = () => {
    clearTimeout(timer)
    if (!visible || !settings?.location) return
    const due = Math.max(0, fetchedAt + settings.refreshMs - Date.now())
    timer = setTimeout(() => {
      void refresh().catch(() => undefined)
    }, due)
  }

  function refresh(): Promise<SkyWeather> {
    const current = settings
    const location = current?.location ?? null
    if (!current || !location) return Promise.reject(noLocationError())
    const key = keyOf(location)
    controller?.abort()
    const aborter = new AbortController()
    controller = aborter
    fetchedAt = Date.now()
    set({ status: snapshot.weather && snapshot.key === key ? "refreshing" : "loading", key, error: null })
    schedule()
    return current.fetchWeather(roundedLocation(location), { signal: aborter.signal }).then(
      (weather) => {
        if (aborter.signal.aborted) return weather
        set({ status: "ready", weather, key, error: null })
        current.onWeather?.(weather, location)
        return weather
      },
      (error: unknown) => {
        if (!aborter.signal.aborted) set({ status: "error", error })
        throw error
      },
    )
  }

  return {
    get: () => snapshot,
    subscribe(listener: () => void) {
      listeners.add(listener)
      return () => listeners.delete(listener)
    },
    refresh,
    configure(next: FeedSettings | null) {
      const moved = keyOf(next?.location ?? null) !== keyOf(settings?.location ?? null)
      settings = next
      if (!next?.location) {
        controller?.abort()
        clearTimeout(timer)
        if (snapshot.status !== "idle") set({ status: "idle", weather: null, key: null, error: null })
        return
      }
      if (moved) {
        fetchedAt = 0
        set({ weather: null })
      }
      schedule()
    },
    setVisible(next: boolean) {
      visible = next
      if (visible) schedule()
      else clearTimeout(timer)
    },
    dispose() {
      const answerPending = snapshot.status === "loading" || snapshot.status === "refreshing"
      if (answerPending) fetchedAt = 0
      controller?.abort()
      clearTimeout(timer)
    },
  }
}

type WeatherFeed = ReturnType<typeof createWeatherFeed>

export { createWeatherFeed, keyOf }
export type { FeedSettings, WeatherFeed, WeatherSnapshot, WeatherStatus }

const radiansPerDegree = Math.PI / 180
const msPerDay = 86_400_000
const julianDayAtUnixEpoch = 2_440_587.5
const julianDayAtJ2000 = 2_451_545
const earthObliquity = 23.4397 * radiansPerDegree

/** Where a body stands in the sky, in radians: `altitude` above the horizon, `azimuth` clockwise from north. */
type SkyPosition = { altitude: number; azimuth: number }

/** The moon's lit part: `fraction` lit from 0 to 1, `phase` from 0 (new) through 0.5 (full) back to 1. */
type MoonPhase = { fraction: number; phase: number; waxing: boolean }

type Equatorial = { rightAscension: number; declination: number }

const daysSinceJ2000 = (date: Date) => date.getTime() / msPerDay + julianDayAtUnixEpoch - julianDayAtJ2000

const rightAscensionOf = (longitude: number, latitude: number) =>
  Math.atan2(
    Math.sin(longitude) * Math.cos(earthObliquity) - Math.tan(latitude) * Math.sin(earthObliquity),
    Math.cos(longitude),
  )

const declinationOf = (longitude: number, latitude: number) =>
  Math.asin(
    Math.sin(latitude) * Math.cos(earthObliquity) + Math.cos(latitude) * Math.sin(earthObliquity) * Math.sin(longitude),
  )

const siderealTime = (days: number, westLongitude: number) =>
  radiansPerDegree * (280.16 + 360.985_623_5 * days) - westLongitude

function horizontal(body: Equatorial, days: number, latitude: number, longitude: number): SkyPosition {
  const phi = latitude * radiansPerDegree
  const hourAngle = siderealTime(days, -longitude * radiansPerDegree) - body.rightAscension
  const altitude = Math.asin(
    Math.sin(phi) * Math.sin(body.declination) + Math.cos(phi) * Math.cos(body.declination) * Math.cos(hourAngle),
  )
  const azimuthFromSouth = Math.atan2(
    Math.sin(hourAngle),
    Math.cos(hourAngle) * Math.sin(phi) - Math.tan(body.declination) * Math.cos(phi),
  )
  return { altitude, azimuth: (azimuthFromSouth + Math.PI) % (2 * Math.PI) }
}

const solarMeanAnomaly = (days: number) => radiansPerDegree * (357.5291 + 0.985_600_28 * days)

function sunEquatorial(days: number): Equatorial & { eclipticLongitude: number } {
  const anomaly = solarMeanAnomaly(days)
  const centre = radiansPerDegree * (1.9148 * Math.sin(anomaly) + 0.02 * Math.sin(2 * anomaly))
  const perihelion = radiansPerDegree * 102.9372
  const eclipticLongitude = anomaly + centre + perihelion + Math.PI
  return {
    eclipticLongitude,
    rightAscension: rightAscensionOf(eclipticLongitude, 0),
    declination: declinationOf(eclipticLongitude, 0),
  }
}

function moonEquatorial(days: number): Equatorial & { distanceKm: number } {
  const meanLongitude = radiansPerDegree * (218.316 + 13.176_396 * days)
  const meanAnomaly = radiansPerDegree * (134.963 + 13.064_993 * days)
  const meanDistance = radiansPerDegree * (93.272 + 13.22935 * days)
  const longitude = meanLongitude + radiansPerDegree * 6.289 * Math.sin(meanAnomaly)
  const latitude = radiansPerDegree * 5.128 * Math.sin(meanDistance)
  return {
    rightAscension: rightAscensionOf(longitude, latitude),
    declination: declinationOf(longitude, latitude),
    distanceKm: 385_001 - 20_905 * Math.cos(meanAnomaly),
  }
}

/** The sun's altitude and azimuth at a place and time, to about a tenth of a degree. */
function sunPosition(date: Date, latitude: number, longitude: number): SkyPosition {
  const days = daysSinceJ2000(date)
  return horizontal(sunEquatorial(days), days, latitude, longitude)
}

/** The moon's altitude and azimuth at a place and time, to about a degree. */
function moonPosition(date: Date, latitude: number, longitude: number): SkyPosition {
  const days = daysSinceJ2000(date)
  return horizontal(moonEquatorial(days), days, latitude, longitude)
}

const sunDistanceKm = 149_598_000

/** How much of the moon is lit at a time, from the sun and moon's elongation. */
function moonPhase(date: Date): MoonPhase {
  const days = daysSinceJ2000(date)
  const sun = sunEquatorial(days)
  const moon = moonEquatorial(days)
  const elongation = Math.acos(
    Math.sin(sun.declination) * Math.sin(moon.declination) +
      Math.cos(sun.declination) * Math.cos(moon.declination) * Math.cos(sun.rightAscension - moon.rightAscension),
  )
  const incidence = Math.atan2(
    sunDistanceKm * Math.sin(elongation),
    moon.distanceKm - sunDistanceKm * Math.cos(elongation),
  )
  const brightLimb = Math.atan2(
    Math.cos(sun.declination) * Math.sin(sun.rightAscension - moon.rightAscension),
    Math.sin(sun.declination) * Math.cos(moon.declination) -
      Math.cos(sun.declination) * Math.sin(moon.declination) * Math.cos(sun.rightAscension - moon.rightAscension),
  )
  const waxing = brightLimb < 0
  const phase = 0.5 + (0.5 * incidence * (waxing ? -1 : 1)) / Math.PI
  return { fraction: (1 + Math.cos(incidence)) / 2, phase, waxing }
}

/** Light from the sun's altitude, in degrees: night below -12°, twilight to 0°, golden hour to 8°, day above. */
type Daylight = "night" | "twilight" | "golden" | "day"

function daylightAt(sunAltitudeDegrees: number): Daylight {
  if (sunAltitudeDegrees < -12) return "night"
  if (sunAltitudeDegrees < 0) return "twilight"
  if (sunAltitudeDegrees < 8) return "golden"
  return "day"
}

export { daylightAt, moonPhase, moonPosition, radiansPerDegree, sunPosition }
export type { Daylight, MoonPhase, SkyPosition }

type Vec3 = { x: number; y: number; z: number }

/** A camera standing in the street, looking north and up: x is east, y up and z north, in metres. */
type SkyCamera = {
  width: number
  height: number
  focal: number
  eye: Vec3
  forward: Vec3
  right: Vec3
  up: Vec3
}

type ScreenPoint = { x: number; y: number; depth: number }

const eyeHeightM = 1.6
const pitchRadians = (78 * Math.PI) / 180
const nearM = 0.3
const landscapeFieldOfViewRadians = (84 * Math.PI) / 180
const portraitFieldOfViewRadians = (72 * Math.PI) / 180

function cameraFor(width: number, height: number): SkyCamera {
  const portrait = height > width
  const field = portrait ? portraitFieldOfViewRadians : landscapeFieldOfViewRadians
  const focal = width / 2 / Math.tan(field / 2)
  return {
    width,
    height,
    focal,
    eye: { x: 0, y: eyeHeightM, z: 0 },
    forward: { x: 0, y: Math.sin(pitchRadians), z: Math.cos(pitchRadians) },
    right: { x: 1, y: 0, z: 0 },
    up: { x: 0, y: Math.cos(pitchRadians), z: -Math.sin(pitchRadians) },
  }
}

const dot = (a: Vec3, b: Vec3) => a.x * b.x + a.y * b.y + a.z * b.z

function toCamera(camera: SkyCamera, point: Vec3): Vec3 {
  const offset = { x: point.x - camera.eye.x, y: point.y - camera.eye.y, z: point.z - camera.eye.z }
  return { x: dot(offset, camera.right), y: dot(offset, camera.up), z: dot(offset, camera.forward) }
}

const projectCamera = (camera: SkyCamera, local: Vec3): ScreenPoint => ({
  x: camera.width / 2 + (camera.focal * local.x) / local.z,
  y: camera.height / 2 - (camera.focal * local.y) / local.z,
  depth: local.z,
})

/** Where a direction (not a point) lands on screen, or null behind the camera. */
function projectDirection(camera: SkyCamera, direction: Vec3): ScreenPoint | null {
  const local = { x: dot(direction, camera.right), y: dot(direction, camera.up), z: dot(direction, camera.forward) }
  return local.z <= 0.01 ? null : projectCamera(camera, local)
}

/** The world direction through a pixel, normalised. */
function rayThrough(camera: SkyCamera, x: number, y: number): Vec3 {
  const sx = x - camera.width / 2
  const sy = camera.height / 2 - y
  const f = camera.focal
  const direction = {
    x: camera.forward.x * f + camera.right.x * sx + camera.up.x * sy,
    y: camera.forward.y * f + camera.right.y * sx + camera.up.y * sy,
    z: camera.forward.z * f + camera.right.z * sx + camera.up.z * sy,
  }
  const length = Math.hypot(direction.x, direction.y, direction.z)
  return { x: direction.x / length, y: direction.y / length, z: direction.z / length }
}

function clipNear(polygon: Vec3[]): Vec3[] {
  const clipped: Vec3[] = []
  for (let index = 0; index < polygon.length; index++) {
    const current = polygon[index]!
    const next = polygon[(index + 1) % polygon.length]!
    const currentIn = current.z >= nearM
    if (currentIn) clipped.push(current)
    if (currentIn !== next.z >= nearM) {
      const t = (nearM - current.z) / (next.z - current.z)
      clipped.push({
        x: current.x + (next.x - current.x) * t,
        y: current.y + (next.y - current.y) * t,
        z: nearM,
      })
    }
  }
  return clipped
}

/** Projects a world polygon, clipped at the near plane; empty when it's all behind the camera. */
function projectPolygon(camera: SkyCamera, polygon: Vec3[]): ScreenPoint[] {
  return clipNear(polygon.map((point) => toCamera(camera, point))).map((local) => projectCamera(camera, local))
}

function skyDirection(altitude: number, azimuth: number): Vec3 {
  return {
    x: Math.cos(altitude) * Math.sin(azimuth),
    y: Math.sin(altitude),
    z: Math.cos(altitude) * Math.cos(azimuth),
  }
}

export { cameraFor, projectDirection, projectPolygon, rayThrough, skyDirection, toCamera }
export type { ScreenPoint, SkyCamera, Vec3 }

import { radiansPerDegree } from "@/components/ui/live-sky-astronomy"
import { skyDirection, type Vec3 } from "@/components/ui/live-sky-camera"
import type { SkyConditions } from "@/components/ui/live-sky-conditions"
import { add, luminance, mix, scale, type Rgb, type SkyPalette } from "@/components/ui/live-sky-palette"

/** The light of one moment: the sky's colours, where the sun and moon are, and how bright the street is. */
type SkyLight = {
  zenith: Rgb
  horizon: Rgb
  glow: Rgb
  glowStrength: number
  sun: Vec3
  sunUp: boolean
  moon: Vec3
  /** The sky's brightness at the zenith, from about 0.02 at night to 1 at noon. */
  ambient: number
  cloudLit: Rgb
  cloudShade: Rgb
  haze: Rgb
  starlight: number
}

type Keyframe = { altitude: number; zenith: Rgb; horizon: Rgb; glow: Rgb; glowStrength: number }

function keyframes(palette: SkyPalette): Keyframe[] {
  return [
    {
      altitude: -18,
      zenith: palette["night-zenith"],
      horizon: palette["night-horizon"],
      glow: palette["night-horizon"],
      glowStrength: 0,
    },
    {
      altitude: -8,
      zenith: palette["blue-zenith"],
      horizon: palette["blue-horizon"],
      glow: palette["dawn-glow"],
      glowStrength: 0.2,
    },
    {
      altitude: -1.5,
      zenith: palette["dawn-zenith"],
      horizon: palette["dawn-horizon"],
      glow: palette["dawn-glow"],
      glowStrength: 0.9,
    },
    {
      altitude: 5,
      zenith: palette["golden-zenith"],
      horizon: palette["golden-horizon"],
      glow: palette["golden-glow"],
      glowStrength: 0.85,
    },
    {
      altitude: 22,
      zenith: palette["day-zenith"],
      horizon: palette["day-horizon"],
      glow: palette["day-glow"],
      glowStrength: 0.45,
    },
  ]
}

function keyframeAt(frames: Keyframe[], altitude: number): Keyframe {
  const first = frames[0]!
  const last = frames.at(-1)!
  if (altitude <= first.altitude) return first
  if (altitude >= last.altitude) return last
  const next = frames.findIndex((frame) => frame.altitude > altitude)
  const from = frames[next - 1]!
  const to = frames[next]!
  const t = (altitude - from.altitude) / (to.altitude - from.altitude)
  return {
    altitude,
    zenith: mix(from.zenith, to.zenith, t),
    horizon: mix(from.horizon, to.horizon, t),
    glow: mix(from.glow, to.glow, t),
    glowStrength: from.glowStrength + (to.glowStrength - from.glowStrength) * t,
  }
}

const smoothstep = (from: number, to: number, value: number) => {
  const t = Math.min(1, Math.max(0, (value - from) / (to - from)))
  return t * t * (3 - 2 * t)
}

function lightFor(conditions: SkyConditions, palette: SkyPalette): SkyLight {
  const sunDegrees = conditions.sun.altitude / radiansPerDegree
  const frame = keyframeAt(keyframes(palette), sunDegrees)
  const grey = mix(palette["cloud-dark"], palette["cloud-light"], 0.55)
  const veil = Math.min(0.92, conditions.cover ** 3 * 0.85 + conditions.gloom * 0.25 + conditions.fog * 0.75)
  const daylight = smoothstep(-14, 14, sunDegrees)
  const ambient = Math.max(0.02, daylight * (1 - 0.3 * conditions.cover * (0.3 + conditions.gloom)))
  const nightCloud = mix(scale(palette["cloud-dark"], 0.18), palette["city-glow"], 0.7)
  const sunTint = mix(palette["cloud-light"], frame.glow, Math.min(1, frame.glowStrength * 0.75))
  const cloudLit = mix(nightCloud, mix(sunTint, palette["cloud-dark"], conditions.gloom * 0.6), daylight)
  const cloudShade = mix(
    scale(nightCloud, 0.6),
    mix(palette["cloud-dark"], scale(palette["cloud-dark"], 0.55), conditions.gloom),
    daylight,
  )
  const veiled = (colour: Rgb) => mix(colour, scale(grey, Math.max(0.08, ambient)), veil)
  return {
    zenith: veiled(frame.zenith),
    horizon: veiled(frame.horizon),
    glow: frame.glow,
    glowStrength: frame.glowStrength * (1 - conditions.cover * 0.6) * (1 - conditions.fog * 0.8),
    sun: skyDirection(conditions.sun.altitude, conditions.sun.azimuth),
    sunUp: sunDegrees > -0.8,
    moon: skyDirection(conditions.moon.altitude, conditions.moon.azimuth),
    ambient,
    cloudLit,
    cloudShade,
    haze: mix(palette.fog, scale(palette.fog, 0.08), 1 - Math.max(ambient, 0.15)),
    starlight: (1 - smoothstep(-16, -7, sunDegrees)) * (1 - conditions.fog),
  }
}

const angleBetween = (a: Vec3, b: Vec3) => Math.acos(Math.min(1, Math.max(-1, a.x * b.x + a.y * b.y + a.z * b.z)))

/** The clear sky's colour in a direction: zenith to horizon by elevation, and a glow around a low sun. */
function skyColourAt(light: SkyLight, direction: Vec3): Rgb {
  const elevation = Math.max(0, direction.y)
  const base = mix(light.horizon, light.zenith, Math.pow(elevation, 0.55))
  const toSun = angleBetween(direction, light.sun)
  const across = Math.hypot(direction.x, direction.z) * Math.hypot(light.sun.x, light.sun.z) || 1
  const sunward = 0.5 + (0.5 * (direction.x * light.sun.x + direction.z * light.sun.z)) / across
  const halo = (Math.exp(-toSun * 1.1) * 0.7 + Math.exp(-toSun * 6) * 0.6) * (1 - elevation * 0.4)
  const wash = 0.22 * sunward * (1 - elevation * 0.6)
  return add(base, scale(light.glow, light.glowStrength * (halo + wash)))
}

const brightness = (light: SkyLight) => luminance(light.zenith) + light.ambient * 0.5

export { brightness, lightFor, skyColourAt, smoothstep }
export type { SkyLight }

import type { SkyPaletteKey } from "@/components/ui/live-sky-palette"

/** How a building is built: granite ashlar, painted render with blinds, white glazed galleries, or modern balconies. */
type BuildingStyle = "stone" | "render" | "galeria" | "modern"

/** A window opening, in metres: its width and height, how high its sill sits above the floor, and how deep it's set in. */
type WindowShape = { width: number; height: number; sill: number; recess: number }

/** Balconies: none, one small one per window on some floors, or a slab along the whole front on every floor. */
type Balconies = "none" | "windows" | "continuous"

/** One building's street front: on the west (-1) or east (1) side, from `start` to `end` north of the viewer, in metres. */
type Building = {
  side: -1 | 1
  start: number
  end: number
  height: number
  /** How far the front stands back from the kerb line. */
  setback: number
  floorHeight: number
  bayWidth: number
  style: BuildingStyle
  material: Extract<SkyPaletteKey, `facade${string}`>
  /** A per-building shift of the material's colour, multiplied in. */
  tint: readonly [number, number, number]
  window: WindowShape
  balconies: Balconies
  /** The window frames' colour: 0 white, 1 dark wood or metal. */
  darkFrames: boolean
  /** How deep the cornice under the roof stands out. */
  cornice: number
  /** Where a wall lantern hangs, if one does. */
  lamp: number | null
  /** A 0 to 1 hash per building, for the windows lit at night and the weathering. */
  seed: number
  /** The heights of the buildings before and after it in the row, 0 at the row's ends. */
  neighbours: readonly [number, number]
}

type Street = { halfWidth: number; buildings: Building[] }

/** A small, fast, seeded generator: the same place always gets the same street. */
function seededRandom(seed: number) {
  let state = seed >>> 0
  return () => {
    state = (state + 0x6d2b79f5) >>> 0
    let mixed = Math.imul(state ^ (state >>> 15), 1 | state)
    mixed = (mixed + Math.imul(mixed ^ (mixed >>> 7), 61 | mixed)) ^ mixed
    return ((mixed ^ (mixed >>> 14)) >>> 0) / 4_294_967_296
  }
}

function hashCoordinates(latitude: number, longitude: number) {
  const text = `${latitude.toFixed(2)},${longitude.toFixed(2)}`
  let hash = 2_166_136_261
  for (let index = 0; index < text.length; index++) hash = Math.imul(hash ^ text.charCodeAt(index), 16_777_619)
  return hash >>> 0
}

const streetStartM = -45
const streetEndM = 230

const styleWeights: readonly (readonly [BuildingStyle, number])[] = [
  ["galeria", 0.3],
  ["stone", 0.25],
  ["render", 0.3],
  ["modern", 0.15],
]

const materialOf: Record<BuildingStyle, Building["material"]> = {
  stone: "facade-stone",
  render: "facade",
  galeria: "facade-gallery",
  modern: "facade-concrete",
}

function pickStyle(random: () => number): BuildingStyle {
  let roll = random()
  for (const [style, weight] of styleWeights) {
    roll -= weight
    if (roll <= 0) return style
  }
  return "render"
}

function windowFor(style: BuildingStyle, bayWidth: number, floorHeight: number, random: () => number): WindowShape {
  if (style === "modern") return { width: bayWidth * 0.78, height: floorHeight - 0.45, sill: 0.15, recess: 0.12 }
  if (style === "stone") return { width: 1.05 + random() * 0.2, height: 1.75, sill: 0.85, recess: 0.38 }
  return { width: 1.1 + random() * 0.3, height: 1.6 + random() * 0.25, sill: 0.9, recess: 0.2 }
}

const tintRange = 0.08

function buildingsAlong(side: -1 | 1, random: () => number): Building[] {
  const buildings: Building[] = []
  let start = streetStartM
  while (start < streetEndM) {
    const width = 9 + random() * 15
    const style = pickStyle(random)
    const floors = 5 + Math.floor(random() * 6)
    const floorHeight = style === "modern" ? 3.05 : 3.1 + random() * 0.45
    const bayWidth = style === "modern" ? 3.2 + random() * 0.8 : 2.4 + random() * 0.9
    const shade = 1 + (random() - 0.5) * tintRange * 2
    buildings.push({
      side,
      start,
      end: start + width,
      height: floors * floorHeight + 1,
      setback: style === "modern" && random() < 0.4 ? random() * 1.2 : 0,
      floorHeight,
      bayWidth,
      style,
      material: materialOf[style],
      tint: [shade * (1 + (random() - 0.5) * 0.06), shade, shade * (1 + (random() - 0.5) * 0.06)],
      window: windowFor(style, bayWidth, floorHeight, random),
      balconies:
        style === "modern" ? "continuous" : style === "galeria" ? "none" : random() < 0.55 ? "windows" : "none",
      darkFrames: style === "modern" || (style !== "galeria" && random() < 0.35),
      cornice: style === "modern" ? 0.25 : 0.45 + random() * 0.35,
      lamp: random() < 0.45 ? start + 1.5 + random() * (width - 3) : null,
      seed: random(),
      neighbours: [0, 0],
    })
    start += width
  }
  return buildings.map((building, index) => ({
    ...building,
    neighbours: [buildings[index - 1]?.height ?? 0, buildings[index + 1]?.height ?? 0],
  }))
}

/** The street around a place: its width and both rows of buildings, the same every time for the same rounded place. */
function streetFor(latitude: number, longitude: number): Street {
  const random = seededRandom(hashCoordinates(latitude, longitude))
  return {
    halfWidth: 6.5 + random() * 2.5,
    buildings: [...buildingsAlong(-1, random), ...buildingsAlong(1, random)],
  }
}

export { seededRandom, streetFor }
export type { Balconies, Building, BuildingStyle, Street, WindowShape }

import { seededRandom } from "@/components/ui/live-sky-street"

/** The side of the square, tiling noise texture the clouds are cut from, in texels. */
const noiseSize = 128

type NoiseTile = { size: number; billow: Uint8Array; detail: Uint8Array }

function latticeOf(cells: number, random: () => number) {
  return Float32Array.from({ length: cells * cells }, () => random())
}

const fade = (t: number) => t * t * (3 - 2 * t)

function valueNoise(lattice: Float32Array, cells: number, u: number, v: number) {
  const x = u * cells
  const y = v * cells
  const x0 = Math.floor(x)
  const y0 = Math.floor(y)
  const tx = fade(x - x0)
  const ty = fade(y - y0)
  const at = (cx: number, cy: number) =>
    lattice[(((cy % cells) + cells) % cells) * cells + (((cx % cells) + cells) % cells)]!
  const top = at(x0, y0) + (at(x0 + 1, y0) - at(x0, y0)) * tx
  const bottom = at(x0, y0 + 1) + (at(x0 + 1, y0 + 1) - at(x0, y0 + 1)) * tx
  return top + (bottom - top) * ty
}

function fractal(octaves: { lattice: Float32Array; cells: number; weight: number }[], u: number, v: number) {
  let sum = 0
  let total = 0
  for (const octave of octaves) {
    sum += valueNoise(octave.lattice, octave.cells, u, v) * octave.weight
    total += octave.weight
  }
  return sum / total
}

let tile: NoiseTile | undefined

/** Two tiling fractal noise fields, made once per page: broad billows for the cloud shapes and fine detail for their edges. */
function noiseTile(): NoiseTile {
  if (tile) return tile
  const random = seededRandom(0x5eed)
  const octavesOf = (cells: number[]) =>
    cells.map((count, index) => ({ lattice: latticeOf(count, random), cells: count, weight: 0.55 ** index }))
  const broad = octavesOf([4, 8, 16, 32, 64])
  const fine = octavesOf([16, 32, 64, 128])
  const billow = new Uint8Array(noiseSize * noiseSize)
  const detail = new Uint8Array(noiseSize * noiseSize)
  for (let y = 0; y < noiseSize; y++) {
    for (let x = 0; x < noiseSize; x++) {
      const u = x / noiseSize
      const v = y / noiseSize
      billow[y * noiseSize + x] = Math.round(fractal(broad, u, v) * 255)
      detail[y * noiseSize + x] = Math.round(fractal(fine, u, v) * 255)
    }
  }
  tile = { size: noiseSize, billow, detail }
  return tile
}

function sampleTile(field: Uint8Array, u: number, v: number) {
  const x = (((u % 1) + 1) % 1) * noiseSize
  const y = (((v % 1) + 1) % 1) * noiseSize
  const x0 = Math.floor(x)
  const y0 = Math.floor(y)
  const tx = x - x0
  const ty = y - y0
  const at = (cx: number, cy: number) => field[(cy % noiseSize) * noiseSize + (cx % noiseSize)]! / 255
  const top = at(x0, y0) + (at(x0 + 1, y0) - at(x0, y0)) * tx
  const bottom = at(x0, y0 + 1) + (at(x0 + 1, y0 + 1) - at(x0, y0 + 1)) * tx
  return top + (bottom - top) * ty
}

export { noiseSize, noiseTile, sampleTile }
export type { NoiseTile }

import { projectDirection, rayThrough, type SkyCamera, type Vec3 } from "@/components/ui/live-sky-camera"
import type { SkyConditions } from "@/components/ui/live-sky-conditions"
import { skyColourAt, type SkyLight } from "@/components/ui/live-sky-light"
import { cssColour, type SkyPalette } from "@/components/ui/live-sky-palette"
import { seededRandom } from "@/components/ui/live-sky-street"

const skyDownscale = 6
const starCount = 520
const moonPoints = 28

type Context = CanvasRenderingContext2D

function paintGradient(context: Context, camera: SkyCamera, light: SkyLight) {
  const width = Math.max(2, Math.ceil(camera.width / skyDownscale))
  const height = Math.max(2, Math.ceil(camera.height / skyDownscale))
  const small = document.createElement("canvas")
  small.width = width
  small.height = height
  const smallContext = small.getContext("2d")
  if (!smallContext) return
  const pixels = smallContext.createImageData(width, height)
  const scaleX = camera.width / width
  const scaleY = camera.height / height
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      const colour = skyColourAt(light, rayThrough(camera, (x + 0.5) * scaleX, (y + 0.5) * scaleY))
      const offset = (y * width + x) * 4
      pixels.data[offset] = Math.min(255, colour[0] * 255)
      pixels.data[offset + 1] = Math.min(255, colour[1] * 255)
      pixels.data[offset + 2] = Math.min(255, colour[2] * 255)
      pixels.data[offset + 3] = 255
    }
  }
  smallContext.putImageData(pixels, 0, 0)
  context.imageSmoothingEnabled = true
  context.imageSmoothingQuality = "high"
  context.drawImage(small, 0, 0, camera.width, camera.height)
}

function paintStars(context: Context, camera: SkyCamera, light: SkyLight, palette: SkyPalette) {
  if (light.starlight < 0.02) return
  const random = seededRandom(0x57a2)
  for (let index = 0; index < starCount; index++) {
    const azimuth = random() * Math.PI * 2
    const altitude = Math.asin(random())
    const magnitude = random() ** 3
    const direction = {
      x: Math.cos(altitude) * Math.sin(azimuth),
      y: Math.sin(altitude),
      z: Math.cos(altitude) * Math.cos(azimuth),
    }
    const point = projectDirection(camera, direction)
    if (!point || point.x < 0 || point.y < 0 || point.x > camera.width || point.y > camera.height) continue
    const size = 0.6 + magnitude * 1.4
    context.fillStyle = cssColour(palette.moon, Math.min(1, (0.25 + magnitude * 0.9) * light.starlight))
    context.fillRect(point.x - size / 2, point.y - size / 2, size, size)
  }
}

function glowAt(context: Context, x: number, y: number, radius: number, colour: SkyPalette["sun"], alpha: number) {
  const gradient = context.createRadialGradient(x, y, 0, x, y, radius)
  gradient.addColorStop(0, cssColour(colour, alpha))
  gradient.addColorStop(0.25, cssColour(colour, alpha * 0.35))
  gradient.addColorStop(1, cssColour(colour, 0))
  context.fillStyle = gradient
  context.fillRect(x - radius, y - radius, radius * 2, radius * 2)
}

function paintSun(
  context: Context,
  camera: SkyCamera,
  light: SkyLight,
  conditions: SkyConditions,
  palette: SkyPalette,
) {
  if (!light.sunUp) return
  const point = projectDirection(camera, light.sun)
  if (!point) return
  const clearness = (1 - conditions.cover * 0.8) * (1 - conditions.fog * 0.7)
  const reach = Math.min(camera.width, camera.height)
  glowAt(context, point.x, point.y, reach * 0.55, light.glow, 0.45 * clearness)
  glowAt(context, point.x, point.y, reach * 0.12, palette.sun, 0.9 * clearness)
  context.beginPath()
  context.arc(point.x, point.y, Math.max(3, camera.focal * 0.006), 0, Math.PI * 2)
  context.fillStyle = cssColour(palette.sun, Math.max(0.35, clearness))
  context.fill()
}

function moonOutline(context: Context, x: number, y: number, radius: number, litFraction: number, waxing: boolean) {
  const side = waxing ? 1 : -1
  const curve = 1 - 2 * litFraction
  context.beginPath()
  context.moveTo(x, y - radius)
  context.arc(x, y, radius, -Math.PI / 2, Math.PI / 2, side < 0)
  for (let step = moonPoints; step >= 0; step--) {
    const along = (step / moonPoints) * 2 - 1
    context.lineTo(x + side * curve * radius * Math.sqrt(1 - along * along), y + along * radius)
  }
  context.closePath()
}

function paintMoon(
  context: Context,
  camera: SkyCamera,
  light: SkyLight,
  conditions: SkyConditions,
  palette: SkyPalette,
) {
  if (conditions.moon.altitude < 0 || light.ambient > 0.6) return
  const point = projectDirection(camera, light.moon)
  if (!point) return
  const radius = Math.max(4, camera.focal * 0.014)
  const veil = (1 - conditions.cover * 0.6) * (1 - conditions.fog * 0.8)
  glowAt(context, point.x, point.y, radius * 9, palette.moon, 0.22 * veil * conditions.moon.fraction)
  context.beginPath()
  context.arc(point.x, point.y, radius, 0, Math.PI * 2)
  context.fillStyle = cssColour(palette.moon, 0.08 * veil)
  context.fill()
  moonOutline(context, point.x, point.y, radius, conditions.moon.fraction, conditions.moon.waxing)
  context.fillStyle = cssColour(palette.moon, 0.95 * veil)
  context.fill()
}

/** Paints the sky behind the clouds: its gradient, the stars, the sun's glare and the moon in its phase. */
function paintSky(
  context: Context,
  camera: SkyCamera,
  light: SkyLight,
  conditions: SkyConditions,
  palette: SkyPalette,
) {
  paintGradient(context, camera, light)
  paintStars(context, camera, light, palette)
  paintMoon(context, camera, light, conditions, palette)
  paintSun(context, camera, light, conditions, palette)
}

const toward = (from: Vec3, to: Vec3): Vec3 => {
  const x = to.x - from.x
  const y = to.y - from.y
  const z = to.z - from.z
  const length = Math.hypot(x, y, z) || 1
  return { x: x / length, y: y / length, z: z / length }
}

export { paintSky, toward }

import { rayThrough, type SkyCamera, type Vec3 } from "@/components/ui/live-sky-camera"
import type { SkyConditions } from "@/components/ui/live-sky-conditions"
import { smoothstep, type SkyLight } from "@/components/ui/live-sky-light"
import { noiseTile, sampleTile } from "@/components/ui/live-sky-noise"
import { mix, scale, type Rgb } from "@/components/ui/live-sky-palette"

/** The cloud deck the shader and the canvas fallback both cut from the noise tile. */
type CloudDeck = {
  /** The deck's height above the viewer, in m. */
  base: number
  /** How many metres of sky one noise tile spans. */
  tile: number
  threshold: number
  softness: number
  /** How much thick cloud darkens toward `shade`, from 0 to 1. */
  shadeBias: number
  lit: Rgb
  shade: Rgb
  horizon: Rgb
  sunGlow: Rgb
  sun: Vec3
  /** The deck's drift, in tiles per second toward east (x) and north (y). */
  drift: { x: number; y: number }
}

const tileM = 5200
const minimumDriftMetresPerSecond = 1.5
const windAloftFactor = 2.2
const aloft = (speed: number) => speed * windAloftFactor

function cloudDeckFor(conditions: SkyConditions, light: SkyLight): CloudDeck {
  const speed = Math.hypot(conditions.wind.east, conditions.wind.north)
  const east = speed > 0.1 ? aloft(conditions.wind.east) : minimumDriftMetresPerSecond
  const north = speed > 0.1 ? aloft(conditions.wind.north) : 0
  const falling = conditions.rainKind !== "none" || conditions.snowRate > 0
  return {
    base: falling ? 900 : 1600,
    tile: tileM,
    threshold: 0.8 - conditions.cover * 0.66,
    softness: 0.12 + conditions.gloom * 0.12 + (falling ? 0.12 : 0),
    shadeBias: 0.45 + conditions.gloom * 0.5,
    lit: light.cloudLit,
    shade: light.cloudShade,
    horizon: mix(light.horizon, light.cloudShade, 0.4),
    sunGlow: light.sunUp ? scale(light.glow, (0.8 + light.glowStrength * 0.7) * (1 - conditions.gloom)) : [0, 0, 0],
    sun: light.sun,
    drift: { x: east / tileM, y: north / tileM },
  }
}

type CloudSample = { colour: Rgb; cover: number }

/** The cloud seen in a direction at an offset, mirrored by the WebGL shader. */
function cloudAt(deck: CloudDeck, direction: Vec3, offset: { x: number; y: number }): CloudSample | null {
  if (direction.y <= 0.02) return null
  const reach = deck.base / Math.max(direction.y, 0.03) / deck.tile
  const u = direction.x * reach + offset.x
  const v = direction.z * reach + offset.y
  const tile = noiseTile()
  const n =
    sampleTile(tile.billow, u, v) * 0.68 + sampleTile(tile.detail, u * 3.07 + offset.y, v * 3.07 + offset.x) * 0.32
  const density = smoothstep(deck.threshold, deck.threshold + deck.softness, n) * smoothstep(0.04, 0.14, direction.y)
  if (density <= 0) return null
  const thick = smoothstep(deck.threshold, deck.threshold + 0.32, n)
  const towardSun = Math.max(0, direction.x * deck.sun.x + direction.y * deck.sun.y + direction.z * deck.sun.z)
  const silver = Math.pow(towardSun, 12) * (1 - thick)
  const lit: Rgb = [
    deck.lit[0] + deck.sunGlow[0] * silver,
    deck.lit[1] + deck.sunGlow[1] * silver,
    deck.lit[2] + deck.sunGlow[2] * silver,
  ]
  const far = smoothstep(0.04, 0.4, direction.y)
  return {
    colour: mix(deck.horizon, mix(lit, deck.shade, thick * deck.shadeBias), far),
    cover: density * (0.55 + 0.45 * far),
  }
}

/** Paints the clouds into a small canvas for the fallback renderer, to be stretched over the sky. */
function paintClouds(target: ImageData, camera: SkyCamera, deck: CloudDeck, offset: { x: number; y: number }) {
  const scaleX = camera.width / target.width
  const scaleY = camera.height / target.height
  const data = target.data
  for (let y = 0; y < target.height; y++) {
    for (let x = 0; x < target.width; x++) {
      const cloud = cloudAt(deck, rayThrough(camera, (x + 0.5) * scaleX, (y + 0.5) * scaleY), offset)
      const index = (y * target.width + x) * 4
      data[index] = cloud ? Math.min(255, cloud.colour[0] * 255) : 0
      data[index + 1] = cloud ? Math.min(255, cloud.colour[1] * 255) : 0
      data[index + 2] = cloud ? Math.min(255, cloud.colour[2] * 255) : 0
      data[index + 3] = cloud ? cloud.cover * 255 : 0
    }
  }
}

export { cloudAt, cloudDeckFor, paintClouds }
export type { CloudDeck }

import type { SkyCamera, Vec3 } from "@/components/ui/live-sky-camera"
import type { SkyConditions } from "@/components/ui/live-sky-conditions"
import type { SkyLight } from "@/components/ui/live-sky-light"
import { mix, scale, type Rgb, type SkyPalette } from "@/components/ui/live-sky-palette"

/** One falling layer, rain or snow, as the particle shader and the canvas fallback both draw it. */
type Fall = {
  kind: "rain" | "snow"
  count: number
  /** Velocity in camera space, m/s: x right, y up the screen, z away from the viewer. */
  velocity: Vec3
  /** A drop's or flake's diameter, in m. */
  diameter: number
  /** How long the shutter stays open, in s: the streak is the path travelled meanwhile. */
  exposure: number
  /** How long one particle lives before it's dealt a new place, in s. */
