import type { SkyCamera } from "@/components/ui/live-sky-camera"
import type { SkyPhotoAnalysis } from "@/lib/sky-photo"

/** A photo of the place to show the live sky in, instead of the drawn street. */
type LiveSkyPhoto = {
  /** The photo's URL: an object URL from a local file, or a same-origin or CORS-enabled URL. */
  src: string
  /** The compass heading of the photo's centre, in degrees from north; from the EXIF, or 180° (south), without it. */
  heading?: number | undefined
  /** The horizontal field of view in degrees; from the EXIF focal length, or 69° (a phone's main camera), without it. */
  fov?: number | undefined
  /** Where the true horizon crosses the photo, from 0 (top) to 1 (bottom); the detected skyline's lowest band without it. */
  horizon?: number | undefined
  /** An image to use as the sky instead of finding it: white is sky, black is the foreground. */
  skyMask?: string | undefined
}

/** The view a photo is drawn with, every field resolved. */
type LiveSkyPhotoView = { heading: number; fov: number; horizon: number }

/** What the renderer draws a photo from: the photo upright, its sky mask, and the windows to light at night. */
type PhotoLayers = {
  image: ImageBitmap
  /** Opaque where the photo is sky. */
  sky: HTMLCanvasElement
  /** Opaque on the window panes to light at night; null when none were found. */
  windows: ImageBitmap | null
  aspect: number
}

const radiansPerDegree = Math.PI / 180
const maxPhotoSide = 2048

/** A camera that looks out of the photo: its heading and the tilt its horizon implies, with its field of view. */
function photoCamera(width: number, height: number, view: LiveSkyPhotoView): SkyCamera {
  const aspect = width / height
  const focalShare = 0.5 / Math.tan((view.fov * radiansPerDegree) / 2)
  const pitch = Math.atan((view.horizon - 0.5) / aspect / focalShare)
  const heading = view.heading * radiansPerDegree
  const forward = {
    x: Math.sin(heading) * Math.cos(pitch),
    y: Math.sin(pitch),
    z: Math.cos(heading) * Math.cos(pitch),
  }
  const right = { x: Math.cos(heading), y: 0, z: -Math.sin(heading) }
  const up = {
    x: -Math.sin(heading) * Math.sin(pitch),
    y: Math.cos(pitch),
    z: -Math.cos(heading) * Math.sin(pitch),
  }
  return { width, height, focal: width * focalShare, eye: { x: 0, y: 1.6, z: 0 }, forward, right, up }
}

async function bitmapOf(url: string, signal: AbortSignal) {
  const response = await fetch(url, { signal })
  if (!response.ok) throw new Error(`The photo answered ${String(response.status)}.`)
  const blob = await response.blob()
  const probe = await createImageBitmap(blob, { imageOrientation: "from-image" })
  const scale = Math.min(1, maxPhotoSide / Math.max(probe.width, probe.height))
  if (scale === 1) return probe
  const resized = await createImageBitmap(blob, {
    imageOrientation: "from-image",
    resizeWidth: Math.round(probe.width * scale),
    resizeHeight: Math.round(probe.height * scale),
    resizeQuality: "high",
  })
  probe.close()
  return resized
}

/** Loads what the renderer needs from a photo already analysed: the photo itself, at most 2048 px on its long side. */
async function loadPhotoLayers(src: string, analysis: SkyPhotoAnalysis, signal: AbortSignal): Promise<PhotoLayers> {
  const [image, windows] = await Promise.all([
    bitmapOf(src, signal),
    analysis.windowsUrl ? bitmapOf(analysis.windowsUrl, signal) : Promise.resolve(null),
  ])
  return { image, sky: analysis.sky, windows, aspect: analysis.aspect }
}

export { loadPhotoLayers, photoCamera }
export type { LiveSkyPhoto, LiveSkyPhotoView, PhotoLayers }

import type { SkyConditions } from "@/components/ui/live-sky-conditions"
import { smoothstep, type SkyLight } from "@/components/ui/live-sky-light"
import { mix, scale, type Rgb, type SkyPalette } from "@/components/ui/live-sky-palette"

/** How a photo of the place is relit for the weather now, whatever light it was taken in. */
type PhotoLighting = {
  /** How bright the scene is, 1 for the light a photo is usually taken in. */
  exposure: number
  /** Overcast's flat, cool, desaturated light, from 0 to 1. */
  overcast: number
  /** A low sun's warm light, from 0 to 1, with `warmTint`. */
  warmth: number
  warmTint: Rgb
  /** Night, from 0 to 1: the scene dims and cools, street lamps wash the lower part and windows light up. */
  night: number
  nightTint: Rgb
  streetLight: Rgb
  wetness: number
  /** What wet ground reflects. */
  sheen: Rgb
  /** Haze toward the horizon, from 0 to 1. */
  haze: number
  hazeColour: Rgb
  windowLight: Rgb
  /** How much of the found windows' glow shows, from 0 by day to 1 at night. */
  windowsOn: number
  /** How much windows glow into the air, as in the street's bloom. */
  bloom: number
}

const hazeByRain = { none: 0, drizzle: 0.05, rain: 0.04, downpour: 0.1 }

function photoLightingFor(conditions: SkyConditions, light: SkyLight, palette: SkyPalette): PhotoLighting {
  const sunDegrees = (conditions.sun.altitude * 180) / Math.PI
  const daylight = smoothstep(-9, 3, sunDegrees)
  const clearness = (1 - conditions.cover * 0.88) * (1 - conditions.fog)
  const night = 1 - daylight
  const visibilityHaze = Math.min(1, 450 / Math.max(60, conditions.visibility))
  return {
    exposure: (1 - 0.22 * conditions.cover * (0.4 + conditions.gloom)) * (0.55 + 0.45 * smoothstep(-2, 12, sunDegrees)),
    overcast: Math.min(1, conditions.cover ** 2 * (0.75 + conditions.gloom * 0.4)),
    warmth: (1 - smoothstep(3, 18, sunDegrees)) * daylight * clearness,
    warmTint: [1.14, 0.94, 0.74],
    night,
    nightTint: [0.72, 0.82, 1.15],
    streetLight: palette["street-light"],
    wetness: conditions.wetness,
    sheen: scale(mix(light.horizon, light.zenith, 0.4), 0.8 + daylight * 0.4),
    haze: Math.min(0.85, visibilityHaze * 0.9 + hazeByRain[conditions.rainKind] + conditions.snowRate * 0.05),
    hazeColour: light.haze,
    windowLight: scale(palette["window-warm"], 1.15),
    windowsOn: smoothstep(0.35, 0.9, night),
    bloom: night * (0.45 + 0.55 * Math.max(conditions.wetness, conditions.fog)) + conditions.fog * 0.1,
  }
}

export { photoLightingFor }
export type { PhotoLighting }

const photoLightingFragment = `
precision mediump float;
uniform sampler2D u_photo;
uniform sampler2D u_skyMask;
uniform sampler2D u_windows;
uniform vec2 u_size;
uniform float u_horizon;
uniform float u_exposure;
uniform float u_overcast;
uniform float u_warmth;
uniform vec3 u_warmTint;
uniform float u_night;
uniform vec3 u_nightTint;
uniform vec3 u_streetLight;
uniform float u_wetness;
uniform vec3 u_sheen;
uniform float u_haze;
uniform vec3 u_hazeColour;
uniform vec3 u_windowLight;
uniform float u_windowsOn;

void main() {
  vec2 uv = gl_FragCoord.xy / u_size;
  float foreground = 1.0 - texture2D(u_skyMask, uv).a;
  if (foreground < 0.004) {
    gl_FragColor = vec4(0.0);
    return;
  }
  vec3 colour = texture2D(u_photo, uv).rgb;
  float grey = dot(colour, vec3(0.2126, 0.7152, 0.0722));
  colour = mix(colour, vec3(grey), 0.45 * u_overcast);
  colour = mix(colour, vec3(0.42) + (colour - vec3(0.42)) * 0.72, u_overcast);
  colour *= mix(vec3(1.0), vec3(0.9, 0.96, 1.06), u_overcast);
  colour *= mix(vec3(1.0), u_warmTint, u_warmth);
  float below = smoothstep(u_horizon - 0.02, min(1.0, u_horizon + 0.35), uv.y);
  colour *= 1.0 - 0.32 * u_wetness * (0.35 + 0.65 * below);
  colour += u_sheen * u_wetness * below * (1.0 - grey) * 0.3;
  colour *= u_exposure;
  colour = mix(colour, colour * u_nightTint * 0.09, u_night);
  colour += u_streetLight * u_night * below * 0.16 * (0.4 + grey);
  colour += u_windowLight * texture2D(u_windows, uv).a * u_windowsOn;
  float far = 1.0 - smoothstep(u_horizon - 0.1, 1.0, uv.y) * 0.75;
  colour = mix(colour, u_hazeColour, clamp(u_haze * far, 0.0, 0.92));
  gl_FragColor = vec4(colour, foreground);
}
`

const photoGlowFragment = `
precision mediump float;
uniform sampler2D u_windows;
uniform vec2 u_size;
uniform vec3 u_windowLight;
uniform float u_windowsOn;
void main() {
  vec2 uv = gl_FragCoord.xy / u_size;
  gl_FragColor = vec4(u_windowLight * texture2D(u_windows, uv).a * u_windowsOn * 1.6, 1.0);
}
`

export { photoGlowFragment, photoLightingFragment }

